// Mock low-CSAT responses (1-2 of 5) from today - swap for helpdesk CSAT export
return [{ json: { responses: [
  { ticketId: 'T-5001', customer: 'Globex', score: 1, comment: 'Took three days and I had to explain my problem twice to two different people.' },
  { ticketId: 'T-5002', customer: 'Initech', score: 2, comment: 'The answer worked but felt copy-pasted, my actual question about self-hosting was ignored.' }
] } }];

const raw = $input.first().json.output ?? '';
const match = String(raw).match(/\{[\s\S]*\}/);
let items = [];
try { items = JSON.parse(match ? match[0] : raw).items || []; } catch (e) { items = []; }
if (!items.length) return [];
const themes = {};
for (const i of items) themes[i.theme] = (themes[i.theme] || 0) + 1;
let body = 'Detractor follow-ups for your approval (NEVER auto-sent, a human owns every apology):\n';
for (const i of items) body += '\n== ' + i.customer + ' (' + i.ticketId + ') | theme: ' + i.theme + ' ==\n' + i.followUpDraft + '\n';
body += '\nTheme tally: ' + Object.entries(themes).map(([t, c]) => t + ' x' + c).join(', ');
body += '\n\nWhy this exists: a detractor who gets a real follow-up becomes your most honest advisor; one who gets silence becomes a churn risk with receipts.';
return [{ json: { subject: 'Detractor follow-ups: ' + items.length + ' draft(s) awaiting your approval', body } }];
